import math

ACTIVATION_X_MIN = 5.0
ACTIVATION_X_MAX = 10.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0

class Memory:
    def __init__(self):
        self.data = {}

    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "unlock_steps": 0,
            "hold_steps": 0,
            "vx": 0.0,
            "vy": 0.0,
            "total_impulse": 0.0,
        }
    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    vx_p, vy_p = sandbox.get_agent_velocity()
    x, y = pd[0], pd[1]
    ty = 1.5  # fixed target y for vertical force
    front, up, down = sandbox.get_whisker_readings()

    # Track collision impulse
    agent_impulse = agent_body.linearImpulse
    magnitude = math.hypot(agent_impulse.x, agent_impulse.y)
    state["total_impulse"] += magnitude

    # Check impulse limit
    if state["total_impulse"] > 60.0:
        fx, fy = 0.0, 0.0
    else:
        if state["phase"] == "APPROACH":
            # Apply strong forward force to move into activation zone
            if front < 0.3:
                # Very close to wall: apply backward force to avoid collision
                fx = -30.0
            elif down < 0.3:
                # Close to floor: apply upward force to avoid collision
                fx = 0.0
            else:
                # Default forward force
                fx = 30.0 if x < 5.0 else 10.0 * (7.0 - x) - 5.0 * vx_p
            fy = 50.0 * (ty - y) - 20.0 * vy_p + _weight_comp(sandbox)

            # Check if in activation zone
            if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vx_p) < 0.5:
                state["phase"] = "UNLOCK"
                state["t"] = 0
                state["unlock_steps"] = 0
        elif state["phase"] == "UNLOCK":
            spd = math.hypot(vx_p, vy_p)
            in_activation = ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX
            if not in_activation:
                # Transition to ESCAPE
                state["phase"] = "ESCAPE"
            else:
                # Check for unlock conditions
                if spd < BACKWARD_SPEED_MAX:
                    state["unlock_steps"] += 1
                else:
                    state["unlock_steps"] = 0
                if state["unlock_steps"] >= 5:
                    # Unlock successful, transition to ESCAPE
                    state["phase"] = "ESCAPE"
                    state["unlock_steps"] = 0
            # Apply forces
            fx_cmd = BACKWARD_FX_THRESHOLD - 1.0  # -35.0 N
            fy_cmd = 50.0 * (ty - y) - 20.0 * vy_p + _weight_comp(sandbox)
            if spd >= BACKWARD_SPEED_MAX * 0.99:
                horiz = -1.5 * vx_p
                if horiz > 0:
                    horiz = 0
                fx_cmd += horiz
                fy_cmd -= 1.5 * vy_p
            fx, fy = fx_cmd, fy_cmd
            state["t"] += 1
            if state["t"] > 60:
                state["phase"] = "ESCAPE"
        elif state["phase"] == "ESCAPE":
            fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vy_p + _weight_comp(sandbox)
            if x >= EXIT_X_MIN and 0.5 <= y <= 2.5:
                state["phase"] = "HOLD"
        elif state["phase"] == "HOLD":
            # Check if still in exit zone
            if x >= EXIT_X_MIN and 0.5 <= y <= 2.5:
                state["hold_steps"] += 1
            else:
                state["hold_steps"] = 0
            if state["hold_steps"] >= 5:
                # Task complete
                pass
            # Apply zero force
            fx, fy = 0.0, _weight_comp(sandbox)
    sandbox.apply_agent_force(fx, fy)

