class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    state = MEM.data.get("initial_state", {
        "phase": "APPROACH",
        "t": 0,
        "lx": None,
        "ly": None,
        "vx": 0.0,
        "vy": 0.0,
        "unlock_streak": 0,
        "hold_streak": 0,
        "total_impulse": 0.0
    })

    pd = sandbox.get_agent_position()
    x, y = pd[0], pd[1]
    vx_p, vy_p = sandbox.get_agent_velocity()
    spd = math.hypot(vx_p, vy_p)

    # Whisker readings
    front, up, down = sandbox.get_whisker_readings()

    # Check for whisker blind band
    in_blind_band = (x >= ACTIVATION_X_MIN and x <= ACTIVATION_X_MAX)

    # Vertical positioning
    if front < 0.3:
        # Move backward to avoid wall
        fx = -20.0
        fy = 0.0
    else:
        # Check if y is within the maze's vertical bounds
        if y < 0.5:
            # Move up
            fy = 20.0
        elif y > 2.5:
            # Move down
            fy = -20.0
        else:
            # Proceed with normal vertical movement
            if up < 0.3:
                # Move down to avoid ceiling
                fy = -20.0
            elif down < 0.3:
                # Move up to avoid floor
                fy = 20.0
            else:
                # Maintain vertical position
                fy = 50.0 * (1.5 - y) - 20.0 * vy_p

    # Horizontal movement
    if state["phase"] == "APPROACH":
        if front < 0.3:
            # Move backward to avoid wall
            fx = -20.0
        else:
            if in_blind_band:
                # In blind band, move forward
                fx = 15.0
            else:
                if x < ACTIVATION_X_MIN:
                    # Move forward
                    fx = 15.0
                elif ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX:
                    # Apply unlock force if conditions met
                    if spd < BACKWARD_SPEED_MAX:
                        fx = -35.0
                    else:
                        fx = 0.0
                else:
                    # Continue forward with velocity adjustment
                    fx = 10.0 * (7.0 - x) - 5.0 * vx_p
    elif state["phase"] == "UNLOCK":
        # Ensure unlock conditions are met
        if spd < BACKWARD_SPEED_MAX and x >= ACTIVATION_X_MIN and x <= ACTIVATION_X_MAX:
            fx = -35.0
            fy = 50.0 * (1.5 - y) - 20.0 * vy_p
            state["unlock_streak"] += 1
            if state["unlock_streak"] >= 5:
                state["phase"] = "ESCAPE"
                state["unlock_streak"] = 0
        else:
            fx = 0.0
            fy = 0.0
            state["unlock_streak"] = 0
    elif state["phase"] == "ESCAPE":
        # Move forward to exit
        if x < EXIT_X_MIN:
            fx = 20.0
        else:
            # Check if in exit zone
            if y >= 0.5 and y <= 2.5:
                # Transition to HOLD
                fx = 0.0
                fy = 0.0
                state["phase"] = "HOLD"
            else:
                # Adjust y to be within the exit zone
                if y < 0.5:
                    # Move up
                    fy = 20.0
                elif y > 2.5:
                    # Move down
                    fy = -20.0
                else:
                    # Maintain y
                    fy = 50.0 * (1.5 - y) - 20.0 * vy_p
                fx = 0.0
    elif state["phase"] == "HOLD":
        # Check if still in exit zone
        if x >= EXIT_X_MIN and y >= 0.5 and y <= 2.5:
            state["hold_streak"] += 1
            if state["hold_streak"] >= 5:
                # Successfully held for 5 steps
                fx = 0.0
                fy = 0.0
        else:
            # Exit zone not met, reset streak
            state["hold_streak"] = 0
            # Adjust movement to get back into exit zone
            if x >= EXIT_X_MIN:
                # y is outside, adjust y
                if y < 0.5:
                    fy = 20.0
                elif y > 2.5:
                    fy = -20.0
                else:
                    fy = 50.0 * (1.5 - y) - 20.0 * vy_p
                fx = 0.0
            else:
                # x < 15.0, move forward
                fx = 20.0
                fy = 0.0

    # Impulse limit enforcement
    impulse_contribution = (fx + fy) * TIME_STEP
    state["total_impulse"] += impulse_contribution
    if state["total_impulse"] > 60.0:
        # Adjust force to stay within impulse limit
        max_allowed = 60.0 - (state["total_impulse"] - impulse_contribution)
        max_force = max_allowed / TIME_STEP
        fx = max(min(fx, max_force), -max_force)
