        if x >= EXIT_X_MIN and y >= 0.5 and y <= 2.5:
            state["hold_streak"] += 1
            if state["hold_streak"] >= 5:
                fx = 0.0
                fy = 0.0
        else:
            state["hold_streak"] = 0
            if x >= EXIT_X_MIN:
                if y < 0.5:
                    fy = 20.0
                elif y > 2.5:
                    fy = -20.0
                else:
                    fy = 50.0 * (1.5 - y) - 20.0 * vy_p
                fx = 0.0
            else:
                fx = 20.0
                fy = 0.0

        fx = max(min(fx, 50.0), -50.0)
        fy = max(min(fy, 50.0), -50.0)

    # Impulse limit enforcement
    impulse_contribution = (fx + fy) * TIME_STEP
    if state["total_impulse"] + impulse_contribution > 60.0:
        max_allowed = 60.0 - state["total_impulse"]
        max_force = max_allowed / TIME_STEP
        fx = max( min(fx, max_force), -max_force )
        fy = max( min(fy, max_force), -max_force )
        # Recalculate impulse contribution with clamped forces
        impulse_contribution = (fx + fy) * TIME_STEP
    state["total_impulse"] += impulse_contribution

    # Cap forces
    fx = max(min(fx, 50.0), -50.0)
    fy = max(min(fy, 50.0), -50.0)

    sandbox.apply_agent_force(fx, fy)

    # Update state
    if state["lx"] is not None:
        state["vx"] = (x - state["lx"]) / TIME_STEP
        state["vy"] = (y - state["ly"]) / TIME_STEP
    state["lx"], state["ly"] = x, y

    MEM.data["initial_state"] = state
